'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var Legend = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Legend, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `zindex` property', function test( t ) {
	var v;

	v = new Legend({
		'fill': 'colorScale'
	});
	t.strictEqual( hasOwnProp( v, 'zindex' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'zindex' ), true, 'returns expected value' );
	t.strictEqual( isNumber( v.zindex ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `zindex` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		'beep',
		null,
		void 0,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var legend = new Legend({
				'fill': 'colorScale'
			});
			legend.zindex = value;
		};
	}
});

tape( 'the constructor returns an instance having a `zindex` property', function test( t ) {
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});
	t.strictEqual( legend.zindex, 0, 'returns expected value' );

	legend = new Legend({
		'fill': 'colorScale',
		'zindex': 5
	});
	t.strictEqual( legend.zindex, 5, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `zindex` property which can be set to a valid value', function test( t ) {
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});

	legend.zindex = 5;
	t.strictEqual( legend.zindex, 5, 'returns expected value' );

	legend.zindex = 10;
	t.strictEqual( legend.zindex, 10, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `zindex` property is set to a new value', function test( t ) {
	var count;
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});
	count = 0;

	legend.on( 'change', onChange );

	legend.zindex = 5;
	t.strictEqual( count, 1, 'returns expected value' );

	legend.zindex = 10;
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	legend.zindex = 10;
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
